{
  "identity": {
    "name": "Cornerstone Comfort (formerly Izzy’s Service)",
    "location": "130 2nd Ave N, Nampa, ID 83687",
    "claims": [
      {
        "statement": "Cornerstone Comfort is a family-owned and operated heating, air, and water company originally founded in 2011 as Izzy’s Service by [redacted].",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "Founded in 2011, (originally Izzy’s Service), Conrerstone Comfort is proudly owned and operated by husband-and-wife team [redacted]"
      },
      {
        "statement": "The business lists its physical address in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "130 2nd Ave N, Nampa, ID 83687"
      },
      {
        "statement": "The company serves residential customers across Boise, Nampa, Meridian, Caldwell, Eagle, Middleton, Kuna, Star, and the greater Treasure Valley.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "Since 2011, [redacted] have proudly served Boise, Meridian, Nampa, Caldwell, Eagle, Kuna, and the surrounding Treasure Valley"
      },
      {
        "statement": "The business is actively transitioning its brand from Izzy’s Service to Cornerstone Comfort, as both names appear across page titles, disclaimers, and body copy.",
        "label": "inference",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": null
      }
    ]
  },
  "industry": {
    "industry": "Residential HVAC and Water Services Contractor",
    "activities": [
      "Heating repair, maintenance, and furnace replacement",
      "Air conditioning installation, repair, and seasonal maintenance",
      "Ductless mini-split system installation and service",
      "Traditional and tankless water heater repair and replacement",
      "Water softener and whole-home water purification system installation",
      "Indoor air quality solutions (air scrubbers, filters, surge protectors)",
      "Recurring HVAC and water heater maintenance memberships (Comfort Club)"
    ],
    "claims": [
      {
        "statement": "Cornerstone Comfort provides residential repair, maintenance, and full system replacement for heating, air conditioning, ductless, water heating, water treatment, and indoor air quality equipment.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/about",
        "quote": "Our licensed and insured team works with furnaces, air conditioners, ductless systems, water heaters, water softeners, water purification systems, and indoor air quality solutions"
      },
      {
        "statement": "The company offers three tiered recurring maintenance memberships (Silver, Gold, and Platinum Comfort Club plans) as well as one-time maintenance visits.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/comfort-club",
        "quote": "Choose from Silver, Gold, or Platinum membership levels and enjoy priority service, regular inspections, and exclusive member savings."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.cornerstonecomfort.net/",
    "claims": [
      {
        "statement": "The company advertises over 500 five-star customer reviews from Treasure Valley homeowners.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "With over 500 five-star reviews from Treasure Valley homeowners, our reputation is built on consistent quality, honest service, and reliable results you can trust."
      },
      {
        "statement": "The website features an online Instant Estimate tool that provides preliminary pricing for HVAC, ductless, and water systems in approximately 60 seconds.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "AI-powered estimates for Heating, Air Conditioning, Ductless, and Water Systems—built on real pricing, real equipment, and real installs."
      },
      {
        "statement": "Standard installations are scoped around a two-person installation crew.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/instant-estimate",
        "quote": "All estimates include standard 2-man installation."
      },
      {
        "statement": "Exact total employee headcount is not disclosed on the website, so whether the company falls within ForgeX's 10 to 75 staff target range is unconfirmed.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "Cornerstone Comfort states on its website footer that it is licensed and insured in Idaho under License #051546.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "Cornerstone Comfort is licensed and insured to perform heating, air conditioning, and water services in Idaho. ​License #051546"
      }
    ],
    "limitations": "Licensing is verified only from the company's self-reported statement (#051546) on its public website; external state licensing databases and corporate registration records were not accessed."
  },
  "existingSoftware": [
    {
      "product": "Wix (wix-thunderbolt, form-app-builder, bookings-uou, faq-builder)",
      "purpose": "Website hosting, content management, native lead/contact forms, and site widgets",
      "evidence": {
        "statement": "The contact page configuration explicitly embeds Wix platform modules including form-app-builder, bookings-uou, and faq-builder under com.wixpress.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "quote": "\"groupId\":\"com.wixpress\",\"artifactId\":\"form-app-builder\""
      }
    },
    {
      "product": "book.housecallpro.com (online scheduling host)",
      "purpose": "External online booking host referenced across site pages",
      "evidence": {
        "statement": "The homepage and other pages reference book.housecallpro.com among external hosts.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "book.housecallpro.com"
      }
    },
    {
      "product": "Housecall Pro (field-service management platform)",
      "purpose": "Field-service scheduling, dispatching, and customer management",
      "evidence": {
        "statement": "Based on the book.housecallpro.com host reference, the business likely uses Housecall Pro as its core field-service management software.",
        "label": "hypothesis",
        "sourceUrl": null,
        "quote": null
      }
    },
    {
      "product": "Google Ads Tag (AW-11223296975) & Google Tag Manager (GTM-5KMJ5LK)",
      "purpose": "Paid search advertising conversion tracking and tag management",
      "evidence": {
        "statement": "The site embeds a Google Ads Tag configuration with ID AW-11223296975 and Google Tag Manager container GTM-5KMJ5LK.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "quote": "\"domain\":\"\",\"name\":\"Google Ads Tag\""
      }
    },
    {
      "product": "Meta Pixel (Facebook Pixel ID 887182607046180)",
      "purpose": "Paid social advertising tracking associated with legacy domain izzysservice.com",
      "evidence": {
        "statement": "The site embeds a custom head script named Meta referencing izzysservice.com and connect.facebook.net.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "quote": "\"domain\":\"izzysservice.com\",\"name\":\"Meta\""
      }
    },
    {
      "product": "Microsoft Clarity",
      "purpose": "Website session recording and heatmap analytics",
      "evidence": {
        "statement": "The site embeds a tracking script named Microsoft Clarity loading from clarity.ms.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "quote": "\"domain\":\"\",\"name\":\"Microsoft Clarity\""
      }
    },
    {
      "product": "On-site AI Instant Estimate Tool",
      "purpose": "Interactive 60-second online price estimator for HVAC, ductless, and water systems",
      "evidence": {
        "statement": "The website offers an AI-powered instant estimator on /instant-estimate that collects system preferences and emails a copy of the estimate.",
        "label": "fact",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "AI-powered estimates for Heating, Air Conditioning, Ductless, and Water Systems—built on real pricing, real equipment, and real installs."
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Across all read pages, the clickable mailto link points to [redacted] (spelled with a 'y'), whereas the legacy domain in the Meta script is izzysservice.com and the visible footer text displays [redacted].",
      "label": "fact",
      "sourceUrl": "https://www.cornerstonecomfort.net/",
      "quote": "[redacted]"
    },
    {
      "statement": "The visible text in the footer and contact sections displays [redacted] as the company email address.",
      "label": "fact",
      "sourceUrl": "https://www.cornerstonecomfort.net/",
      "quote": "[redacted]"
    },
    {
      "statement": "The contact page presents two separate Wix forms ('Get a Price Quote' and 'Let’s Talk Comfort') alongside a 'Schedule Now' booking option.",
      "label": "fact",
      "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
      "quote": "Get a Price Quote First name * Last name * Email * Phone * Select a Service * Choose an option"
    },
    {
      "statement": "The Comfort Club page uses a standalone Wix form ('Join the Comfort Club Today') that asks customers to select Silver, Gold, or Platinum and Monthly or Yearly billing without an integrated checkout or automated onboarding flow visible on the page.",
      "label": "fact",
      "sourceUrl": "https://www.cornerstonecomfort.net/comfort-club",
      "quote": "Join the Comfort Club Today First name * Last name * Email * Phone *"
    },
    {
      "statement": "The Instant Estimate page generates an online estimate and emails a copy to the homeowner, requiring a subsequent in-home evaluation to finalize a fixed price.",
      "label": "fact",
      "sourceUrl": "https://www.cornerstonecomfort.net/instant-estimate",
      "quote": "You’ll answer a few quick questions, then we’ll show your estimate and email you a copy."
    },
    {
      "statement": "Because customer inquiries enter through multiple separate paths—online scheduling via book.housecallpro.com, at least three distinct Wix form types, the Instant Estimate tool, phone calls, and a misconfigured mailto link—the business has fragmented lead capture while actively paying for Google Ads and Meta traffic.",
      "label": "inference",
      "sourceUrl": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Direct email inquiries initiated by clicking the website's email link are routed to '[redacted]' (a probable typo for the former 'izzysservice.com' domain) rather than '[redacted]', creating an immediate risk of bounced or lost customer leads.",
      "label": "fact",
      "basis": "Observed directly on https://www.cornerstonecomfort.net/ and all subpages: the mailto link is '[redacted]', while the visible text is '[redacted]' and the Meta embed domain is 'izzysservice.com'."
    },
    {
      "problem": "Lead and booking intake is split across Wix native forms (quote requests, general contact, Comfort Club signups), an Instant Estimate tool, and external book.housecallpro.com links.",
      "label": "inference",
      "basis": "Inferred from the presence of Wix form-app scripts and forms alongside book.housecallpro.com references and the /instant-estimate page."
    },
    {
      "problem": "Leads submitted through Wix forms ('Get a Price Quote', 'Let’s Talk Comfort', 'Join the Comfort Club Today') and the Instant Estimate tool may not automatically sync into their field-service software within two minutes, potentially causing manual data entry overhead or delayed follow-up on high-value installation estimates.",
      "label": "hypothesis",
      "basis": "Wix forms and custom instant estimators typically send email notifications to a shared inbox unless custom webhook/API automation is configured to push leads into field-service software."
    },
    {
      "problem": "With active paid advertising on Google Ads (AW-11223296975) and Meta (connect.facebook.net) driving traffic across multiple conversion paths, the owners may lack a single weekly report connecting ad spend by channel to actual booked jobs and closed revenue.",
      "label": "hypothesis",
      "basis": "Small home-service contractors using Wix and field-service software rarely have automated attribution tying Google and Meta ad spend to closed job revenue in their field-service and accounting systems."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Wix Editor mailto link correction",
      "addresses": "Fixes the '[redacted]' typo in the clickable email links across the website header/footer so emails go to '[redacted]'.",
      "alreadyOwned": true
    },
    {
      "solution": "Native online booking and lead capture widgets from their existing field-service software (book.housecallpro.com)",
      "addresses": "Replacing or connecting Wix native quote forms with native field-service lead forms so web inquiries land directly in the dispatch/CRM system without custom middleware.",
      "alreadyOwned": true
    },
    {
      "solution": "Wix Automations",
      "addresses": "Sends basic automated confirmation emails when a visitor submits a Wix form ('Get a Price Quote' or 'Join the Comfort Club Today').",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [
    {
      "name": "Revenue Leak Check",
      "kind": "catalog",
      "description": "One-week audit ($500 fixed price, credited in full toward any fix ordered within 30 days) examining how many calls, Wix form submissions, Instant Estimate completions, and misrouted emails slip through without a booked job, and quantifying their revenue value.",
      "problem": "Fragmented lead intake across Wix forms, Instant Estimate, phone calls, and the misconfigured mailto link while spending on Google and Meta ads.",
      "whyNotExistingSoftware": "Existing software platforms (Wix, Google Ads, and field-service software) each track only their own silo and do not audit cross-channel lead drop-off, unfollowed instant estimates, or broken contact links."
    },
    {
      "name": "Lead-to-job pipeline",
      "kind": "catalog",
      "description": "Automated pipeline ($1,800 setup plus $149/month) ensuring every lead from Wix quote forms, Comfort Club signup forms, and the Instant Estimate tool lands directly in their field-service software within two minutes, triggers an immediate personalized reply, and creates a tracked follow-up task so no estimate or inquiry goes uncalled.",
      "problem": "Potential manual re-entry or slow follow-up on Wix form submissions and 60-second Instant Estimate leads that require an in-home evaluation to close.",
      "whyNotExistingSoftware": "While their booking software handles direct appointment slots, custom multi-step flows like the Instant Estimate tool and Comfort Club plan selection forms on Wix do not natively create structured customer records, estimates, and automated follow-up sequences inside field-service software without custom integration."
    },
    {
      "name": "Owner's Monday numbers",
      "kind": "catalog",
      "description": "Weekly one-page summary ($1,200 setup plus $99/month) delivered every Monday showing booked revenue, close rate, average ticket, cost per booked job by lead source, and accounts receivable across their field-service software, accounting software, and Google/Meta ad accounts.",
      "problem": "Lack of unified visibility into return on ad spend across Google Ads, Meta Ads, Instant Estimate leads, and completed field jobs.",
      "whyNotExistingSoftware": "Native dashboards in Wix, Google Ads, Meta Ads, and field-service software do not combine ad spend and accounting receivables with closed job data into a single source-attributed owner report."
    }
  ],
  "feasibility": {
    "rating": "high",
    "explanation": "Wix forms and webhook triggers, Google/Meta ad reporting APIs, and standard field-service management APIs/webhooks are well-documented and straightforward to integrate using standard automation workflows."
  },
  "aiDelivery": {
    "rating": "partly",
    "explanation": "Deterministic workflow automation (webhooks, API integrations, and SQL/data aggregation) should handle lead routing, CRM record creation, and Monday financial reporting for reliability, while AI agents can assist in drafting personalized follow-up messages based on the homeowner's Instant Estimate selections or triaging free-text form inquiries."
  },
  "humanReview": [
    "Owner or office manager review before sending any non-standard pricing or custom technical responses to homeowners.",
    "In-home technician evaluation and human approval are explicitly required before issuing a final fixed installation price following an online Instant Estimate.",
    "Human verification of Comfort Club recurring billing setup and plan eligibility before charging a customer."
  ],
  "risks": [
    {
      "type": "compliance",
      "description": "Automated SMS or email replies triggered by Wix forms or the Instant Estimate tool must comply with TCPA and CAN-SPAM consent rules, ensuring opt-in language on Wix forms covers automated follow-up."
    },
    {
      "type": "operational",
      "description": "Ongoing rebranding from Izzy’s Service to Cornerstone Comfort creates a risk of inconsistent sender names, domains, or duplicate customer records if legacy and new domains are not normalized during integration."
    },
    {
      "type": "security",
      "description": "Customer PII (names, home addresses, phone numbers, and equipment details) transmitted between Wix forms and field-service software must be encrypted in transit and stored with least-privilege API credentials."
    }
  ],
  "commercial": {
    "supportable": true,
    "value": "Illustrative gross revenue impact of $5,760/year from converting 2 additional Gold Comfort Club memberships per month (24/year × $240/year published price), plus an illustrative $9,800/year from recovering 1 additional standard hot water heater replacement per quarter (4/year × $2,450 published special price), or $21,996/year if recovering 1 tankless water heater installation per quarter (4/year × $5,499 published special price).",
    "implementationCost": "Revenue Leak Check: $500 fixed price (credited in full if a fix is ordered within 30 days). Lead-to-job pipeline: $1,800 setup + $149/month ($3,588 in year one). Owner's Monday numbers: $1,200 setup + $99/month ($2,388 in year one).",
    "assumptions": [
      "Illustrative calculation uses published prices on https://www.cornerstonecomfort.net/comfort-club ($139 one-time maintenance; $200/year Silver; $240/year Gold; $500/year Platinum) and https://www.cornerstonecomfort.net/specials ($2,450 Hot Water Heater; $4,899 Whole Home Water Softener & Filter; $5,499 Tankless Water Heater; $850 Air Scrubber; $200 Surge Protector).",
      "Assumes fixing misrouted email links and automating sub-2-minute lead follow-up across Wix forms and the Instant Estimate tool recovers an illustrative 2 Gold Comfort Club plans per month (24/year) and 1 hot water heater or tankless water heater installation per quarter (4/year).",
      "Figures represent illustrative gross revenue based on published site prices, not net profit or guaranteed results."
    ]
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Co-Owner",
      "General Manager / Office Manager"
    ],
    "people": [
      {
        "name": "[redacted]",
        "role": "Co-Owner",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "Founded in 2011, (originally Izzy’s Service), Conrerstone Comfort is proudly owned and operated by husband-and-wife team [redacted]"
      },
      {
        "name": "[redacted]",
        "role": "Co-Owner",
        "sourceUrl": "https://www.cornerstonecomfort.net/",
        "quote": "Founded in 2011, (originally Izzy’s Service), Conrerstone Comfort is proudly owned and operated by husband-and-wife team [redacted]"
      }
    ],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://www.cornerstonecomfort.net/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "When a homeowner completes your 60-second Instant Estimate or submits the 'Get a Price Quote' or 'Comfort Club' forms on Wix, does that information land automatically in your scheduling software, or does someone in the office enter it by hand?",
      "Were you aware that the clickable email link on your website currently points to '[redacted]' (with a 'y') rather than '[redacted]'?",
      "How quickly is your team currently able to follow up with homeowners who generate an online Instant Estimate to get their in-home evaluation booked?",
      "Between Google Ads, Meta Ads, and organic traffic, how do you currently track which ad channel produces booked installations versus just clicks or form fills?",
      "How many technicians and office staff are currently on your team handling incoming calls, estimates, and dispatch?"
    ],
    "outreachSubject": "Quick heads-up on a broken email link on cornerstonecomfort.net + lead routing question",
    "outreachBody": "Hi [redacted],\n\nI was looking through Cornerstone Comfort's website and noticed a quick technical issue from the rebrand from Izzy's Service: while your page text lists [redacted], the clickable email link across the site actually points to [redacted] (spelled with a \"y\"). Anyone clicking that link to email you is likely getting a bounce.\n\nI also noticed you're running Google and Meta ads while capturing leads across several different places—your 60-second Instant Estimate tool, Wix quote and Comfort Club forms, and online scheduling.\n\nI run ForgeX ([ForgeX Website Placeholder]), where we help family-owned HVAC and plumbing contractors connect their web forms, instant estimators, and ad accounts directly into their field-service software. Before recommending any software work, we offer a fixed-price Revenue Leak Check ($500) that audits how many calls, form leads, and instant estimates slip through the cracks over one week—and the $500 is credited in full if you decide to have us build a fix within 30 days. We don't promise specific revenue results, and sometimes the best answer is a simple tweak to the tools you already own.\n\nWould you be open to a brief 10-minute call next week to see if your Instant Estimate and Wix form leads are syncing cleanly into your dispatch system?\n\nBest regards,\n\n[Founder Name]\n[Founder Title], ForgeX\n[Founder Phone Number]\n[ForgeX Street Address, City, State, ZIP]\n\nIf you prefer not to receive future emails from me, simply reply with \"unsubscribe\" or \"opt out\" and I will remove you immediately."
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.cornerstonecomfort.net/",
        "usedFor": "Business identity, Nampa physical address, ownership ([redacted]), Idaho license #051546, 500+ 5-star reviews, Instant Estimate overview, book.housecallpro.com reference, and mailto link discrepancy ([redacted] vs [redacted])."
      },
      {
        "url": "https://www.cornerstonecomfort.net/about",
        "usedFor": "Principal HVAC and water business activities, mission, and residential service scope."
      },
      {
        "url": "https://www.cornerstonecomfort.net/contact-cornerstone-comfort",
        "usedFor": "Embedded Wix configuration (com.wixpress, form-app-builder, bookings-uou), Google Ads Tag (AW-11223296975), Meta pixel (izzysservice.com), Microsoft Clarity, and multiple Wix intake forms."
      },
      {
        "url": "https://www.cornerstonecomfort.net/instant-estimate",
        "usedFor": "Instant Estimate workflow details, 2-man installation crew assumption, and in-home evaluation requirement."
      },
      {
        "url": "https://www.cornerstonecomfort.net/comfort-club",
        "usedFor": "Published pricing for Comfort Club maintenance plans ($19.99/mo or $200/yr Silver; $24.99/mo or $240/yr Gold; $44.99/mo or $500/yr Platinum) and one-time maintenance ($139), plus the Comfort Club signup form."
      },
      {
        "url": "https://www.cornerstonecomfort.net/specials",
        "usedFor": "Published equipment and service special prices ($2,450 Hot Water Heater, $5,499 Tankless Water Heater, $4,899 Whole Home Water Softener & Filter, $850 Air Scrubber, $200 Surge Protector, $1,500 off Trane HVAC System)."
      },
      {
        "url": "https://www.cornerstonecomfort.net/services",
        "usedFor": "Verification of core service lines and Treasure Valley service areas."
      }
    ],
    "limitations": [
      "Exact employee headcount is not stated on the public website; only 'standard 2-man installation' and 'Our licensed and insured team' are mentioned, so whether the company has 10 to 75 staff cannot be confirmed without discovery.",
      "Back-office integrations between Wix forms, the Instant Estimate tool, and their field-service software cannot be observed from public client-side code.",
      "Accounting software (such as QuickBooks) and internal call-handling processes are not visible on the website.",
      "State contractor licensing (#051546) is self-reported on the website and was not cross-checked against external state databases."
    ]
  },
  "qualification": {
    "category": "pursue now",
    "rationale": "Cornerstone Comfort is an owner-led residential HVAC and water contractor in Nampa, Idaho (founded in 2011 by [redacted], with 500+ five-star reviews) that actively pays for leads via Google Ads (AW-11223296975) and Meta Ads. Publicly observable facts on the website point directly to lead-capture and routing issues that ForgeX's Revenue Leak Check and Lead-to-job pipeline address: (1) a broken/misspelled clickable email link ('[redacted]') across all pages during their rebrand from Izzy's Service to Cornerstone Comfort, and (2) fragmented lead intake split across multiple native Wix forms ('Get a Price Quote', 'Let’s Talk Comfort', 'Join the Comfort Club Today'), a 60-second Instant Estimate tool requiring follow-up for in-home evaluation, and external book.housecallpro.com scheduling links. A verified business contact channel ([redacted]) and named owner decision-makers exist, making this a strong candidate for immediate outreach while verifying team headcount during discovery."
  }
}
